using System;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class SpawnTimingTests {
 static int checks;static void Check(bool v,string m){checks++;if(!v)throw new Exception(m);}static void Near(double a,double b,string m,double e=3e-5){Check(Math.Abs(a-b)<e,m+": "+a+" != "+b);}
 static Track E(string id="p"){return new Track{id=id,kind="emitter",start=0,end=0,x=100,y=0,count=1,speed=0,life=100,advancedBullets=true};}
 static Track Child(string id="child"){var t=E(id);t.templateOnly=true;t.x=t.y=0;return t;}
 static BulletAction Spawn(string target="child",string timing="action-time"){return new BulletAction{type="spawn",templateId=target,spawnTiming=timing,start=1,duration=0,maxGeneration=3};}
 static EditorState S(params Track[] t){var s=new EditorState{duration=300,tracks=t.ToList()};Motion.Normalize(s);return s;}
 static SimBullet B(BulletWorld w,string id){return w.bullets.Single(b=>b.source.id==id);}
 static void Main(){
 foreach(string timing in new[]{"after-move","action-time"}){var p=E();p.bulletActions.Add(Spawn("child",timing));var orbit=new Track{id="orbit",kind="control",start=1,end=1,eventPreset="orbit-bullets",targetSource="p",eventCenterX=0,eventCenterY=0,eventOrbitSpeed=.8,eventResetLife=false};var w=new BulletWorld(S(p,Child(),orbit));w.Seek(1);var c=B(w,"child");Near(c.x,timing=="action-time"?100:100*Math.Cos(.8*Math.PI/180),"orbit copy x "+timing);Near(c.y,timing=="action-time"?0:-100*Math.Sin(.8*Math.PI/180),"orbit copy y "+timing);w.Seek(0);w.Seek(1);Near(B(w,"child").x,c.x,"reverse orbit copy");}
 {var p=E();p.y=200;p.rawAlpha=true;p.moveOnBirth=true;p.bulletActions.Add(new BulletAction{type="alpha",duration=0,to=2});p.bulletActions.Add(new BulletAction{type="speed",duration=0,to=3});p.bulletActions.Add(new BulletAction{type="scale",duration=0,to=2});p.bulletActions.Add(new BulletAction{type="direction",duration=0,to=90});var a=Spawn();a.start=0;a.inheritAngle=a.inheritScale=true;a.expressions["spawnAngle"]="alpha";a.expressions["spawnOffsetX"]="speed+n+volley+source.x";p.bulletActions.Add(a);p.bulletActions.Add(new BulletAction{type="alpha",duration=0,to=4});p.bulletActions.Add(new BulletAction{type="speed",duration=0,to=9});p.bulletActions.Add(new BulletAction{type="scale",duration=0,to=5});p.bulletActions.Add(new BulletAction{type="direction",duration=0,to=0});var child=Child();child.speed=1;child.moveOnBirth=true;child.alpha=.6;var w=new BulletWorld(S(p,child));w.Seek(0);var c=B(w,"child");Near(c.x,100+105*Math.Cos(92*Math.PI/180),"live x speed n source alpha and birth move");Near(c.y,200-105*Math.Sin(92*Math.PI/180),"live direction offset");Near(c.scale,2,"capture scale before mutation");Near(c.alpha,.6,"no invented alpha inheritance");Near(c.sourceX,100,"child source center snapshot x");Near(c.sourceY,200,"child source center snapshot y");Near(B(w,"p").x,109,"parent later speed and movement");Near(B(w,"p").alpha,4,"parent later alpha");Near(B(w,"p").scale,5,"parent later scale");}
 {var p=E();var a=Spawn();a.start=0;a.duration=10;a.condition="age>=2";a.once=true;p.bulletActions.Add(a);var w=new BulletWorld(S(p,Child()));w.Seek(1);Check(w.bullets.Count==1,"false does not create");w.Seek(2);Check(w.bullets.Count==2&&B(w,"p").firedActions.Count==1,"true consumes once");w.Seek(8);Check(w.bullets.Count==2,"once holds");w.Seek(1);Check(B(w,"p").firedActions.Count==0,"reverse once");w.Seek(8);Check(w.bullets.Count==2,"repeat once");}
 {var p=E();var a=Spawn();a.start=0;a.spawnRepeat=2;a.duration=0;p.bulletActions.Add(a);var w=new BulletWorld(S(p,Child()));w.Seek(8);Check(w.bullets.Count(b=>b.source.id=="child")==5,"repeat duration zero continues");}
 foreach(string fx in new[]{"none","fade"}){var p=E();p.speed=7;p.deathEffect=fx;p.deathFrames=4;var a=Spawn();a.start=2;a.destroyParent=true;p.bulletActions.Add(a);p.bulletActions.Add(new BulletAction{type="speed",start=2,duration=0,to=100});p.bulletActions.Add(new BulletAction{type="alpha",start=2,duration=0,to=.2});var w=new BulletWorld(S(p,Child()));w.Seek(1);var old=B(w,"p");w.Seek(2);Near(B(w,"child").x,107,"destroy parent spawn position");Near(old.x,107,"destroy stops this frame move "+fx);Near(old.speed,7,"destroy stops later behavior");Near(old.alpha,1,"destroy stops later alpha");Check(fx=="none"?old.dead:old.deathStart==2,"death effect semantics");}
 {var p=E();p.bulletActions.Add(new BulletAction{type="clear",start=1,duration=0});p.bulletActions.Add(Spawn());var w=new BulletWorld(S(p,Child()));w.Seek(1);Check(w.bullets.Count==0,"prior clear blocks immediate spawn");}
 {var p=E();var a=Spawn();a.maxGeneration=1;p.bulletActions.Add(a);var c=Child();c.bulletActions.Add(Spawn("child"));c.bulletActions[0].start=0;c.bulletActions[0].maxGeneration=1;c.moveOnBirth=true;c.speed=2;var w=new BulletWorld(S(p,c));w.Seek(1);Check(w.bullets.Count==2,"generation cap");Near(B(w,"child").x,102,"new child ticks once only");}
 {var p=E();var a=Spawn("missing");a.once=true;a.destroyParent=true;p.bulletActions.Add(a);var w=new BulletWorld(S(p));w.Seek(1);Check(B(w,"p").firedActions.Count==0&&!B(w,"p").dead,"missing target neither consumes nor destroys");}
 {var p=E();var a=Spawn();p.bulletActions.Add(a);var s=S(p,Child());var ser=new JavaScriptSerializer();var back=ser.Deserialize<EditorState>(ser.Serialize(s));Motion.Normalize(back);Check(back.tracks[0].bulletActions[0].spawnTiming=="action-time","JSON timing");Check(s.Snapshot().tracks[0].bulletActions[0].spawnTiming=="action-time","snapshot timing");Check(BulletSystem.CloneTracks(s.tracks)[0].bulletActions[0].spawnTiming=="action-time","copy timing");Check(TrackPreset.Capture("timing",s.tracks,50).Instantiate(0,50)[0].bulletActions[0].spawnTiming=="action-time","preset timing");Check(ser.Deserialize<BulletAction>("{}").spawnTiming=="after-move","missing default");}
 {var p=E();var a=Spawn();a.spawnTiming=null;p.bulletActions.Add(a);bool rejected=false;try{S(p,Child());}catch(FormatException){rejected=true;}Check(rejected,"explicit null timing rejects consistently");}
 foreach(string kind in new[]{"object","group","control"}){var p=E();p.kind=kind;p.bulletActions.Add(Spawn());bool rejected=false;try{S(p,Child());}catch(FormatException){rejected=true;}Check(rejected,"unsupported source rejects "+kind);}
 Console.WriteLine("PASS SpawnTiming "+checks+" checks");
 }
}
